{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "The closest analogue (benzimidazole-piperidine, Morgan 0.39) is brain-permeable with B/Pb 2.7, showing the core scaffold can cross the BBB as a lipophilic base; however, it lacks the query's ionizable carboxylic acid and ethoxyethyl group, so this positive result does not transfer to the zwitterionic query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Benperidol shows rapid brain localization by PET in baboons, but it is a lipophilic butyrophenone with no acid and only 0.32 similarity, providing no support for the query's acid-containing zwitterion crossing the BBB.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "SA4503 has high receptor-specific brain uptake in rats, but it is a lipophilic sigma ligand with no ionizable acid and low similarity (0.30), so it does not model the query's poor passive permeability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "A benzimidazole-containing compound reaches 13 µM in rat brain after IP dosing, confirming benzimidazoles can be CNS-penetrant, but it lacks the query's carboxylic acid and full ionization, limiting transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "A secondary amide analogue has CNS br/bl 2.3, but it is a lipophilic base/amide without the query's acid, so it does not transfer to the zwitterionic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a zwitterionic benzimidazole-piperidine with a carboxylic acid and basic amine, fully ionized at pH 7.4, very low logD, and high rotatable bond count, predicting poor passive BBB permeability. The closest experimental analogues are lipophilic CNS-permeable bases lacking the acid, so their positive brain penetration does not transfer. Therefore, meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No experimental brain/plasma/CSF data for the query or close analogues containing the same carboxylic acid/zwitterion.",
    "No efflux transporter (P-gp/BCRP) or active uptake transporter data for the query.",
    "In silico logD and pKa estimates may have errors."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

